args.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, sans-serif;
  line-height: 1.7;
  color: #1a1a1a;
  background: #fafafa;
  padding: 2rem;
}

main {
  max-width: 640px;
  margin: 0 auto;
  padding: 3rem 0;
}

h1 {
  font-size: 2rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: #0a0a0a;
}

.mission {
  font-size: 1.1rem;
  color: #4a5568;
  margin-bottom: 3rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid #e2e8f0;
}

section {
  margin-bottom: 2.5rem;
}

h2 {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
  color: #2d3748;
}

p {
  margin-bottom: 1rem;
  color: #4a5568;
}

ul {
  list-style: none;
  margin-bottom: 1rem;
}

li {
  margin-bottom: 0.75rem;
  color: #4a5568;
}

li strong {
  color: #2d3748;
}

a {
  color: #3182ce;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

footer {
  max-width: 640px;
  margin: 0 auto;
  padding-top: 2rem;
  border-top: 1px solid #e2e8f0;
  color: #a0aec0;
  font-size: 0.875rem;
}
